export const code = "import csv\n\ndef read_expenses(path):\n    rows = []\n    with open(path) as f:\n        for row in csv.DictReader(f):\n            try:\n                rows.append((row[\"category\"], float(row[\"amount\"])))\n            except ValueError:\n                print(\"Skipping bad row:\", row[\"date\"])\n    return rows\n\ndef totals_by_category(rows):\n    totals = {}\n    for category, amount in rows:\n        totals[category] = totals.get(category, 0) + amount\n    return totals\n\ndef write_summary(totals, path):\n    with open(path, \"w\") as f:\n        for category in sorted(totals):\n            f.write(f\"{category}: {totals[category]:.2f}\\n\")\n\nrows = read_expenses(\"expenses.csv\")\ntotals = totals_by_category(rows)\nwrite_summary(totals, \"summary.txt\")\nprint(\"Total spent:\", sum(totals.values()))\n";

